      cordelPages: {
        'quintal': { title: 'El Patio al Amanecer', text: 'En un patio de tierra blandita\nnació una mandioca chiquita.\nEl gallo cantó tres veces\ny la mañana fue bienvenida.', hint: 'Haz clic en la regadera para regar el brote.', say: 'GLUP GLUP!', done: 'EL BROTE CRECIO!' },
        'convite': { title: 'La Invitación del Viento', text: 'Pasó un viento travieso\nllevando un papelito:\nera la invitación a San Juan,\ncon banderitas y cariño.', hint: 'Haz clic en la invitación para atraparla en el aire.', say: 'CASI!', done: 'ATRAPASTE LA INVITACION!' },
        'cozinha': { title: 'La Cocina de Canjica', text: 'En la cocina de Canjica\nel fogón echaba humo.\nRevuelve aquí, revuelve allá,\ny la olla cantaba al mundo.', hint: 'Haz clic en la olla para revolver la canjica.', say: 'REVUELVE!', done: 'EN SU PUNTO!' },
        'fogueira': { title: 'La Fogata Encendida', text: 'Cuando la noche creció\nla fogata se encendió.\nTodos bailaron juntos\ny la mandioca creció.', hint: 'Haz clic en la leña para echar un tronco al fuego.', say: 'CRAC!', done: 'FOGATA Y FIESTA!' },
        'balao': { title: 'El Globo de Papel', text: 'Soltó un globo de papel\ncon un deseo de corazón.\nEl globo parpadeó raro\ny subió sin dirección!', hint: 'Haz clic en el globo para que suba.', say: 'SUBE!', done: 'LEJOS, MUY LEJOS!' },
        'lua': { title: 'La Luna de Queso', text: 'Subió, pasó nubes y estrellas,\nfue a parar a la luna, entonces.\nY la luna era de queso,\ncon huecos y olor a pan.', hint: 'Haz clic en los cráteres para ver quién vive ahí.', say: 'PLOP!', done: 'LA LUNA TIENE VECINOS!' },
        'dj': { title: 'El Conejo DJ', text: 'En la luna vivía un conejo\ntocando forró espacial.\nLa mandioca bailó tanto\nque se mareó y perdió la señal.', hint: 'Haz clic en el tocadiscos del DJ para cambiar la música.', say: 'TUNTS TUNTS!', done: 'PISTA EN LLAMAS!' },
        'submarino': { title: 'El Submarino de Calabaza', text: 'Cayó de la luna en picada\nal fondo azul del mar.\nSubió a un submarino de calabaza\ncon un pez para ayudar.', hint: 'Haz clic en el periscopio para que suene el sonar.', say: 'PIIIN!', done: 'ENCONTRO UN CARDUMEN!' },
        'doces': { title: 'La Ciudad de Cocada', text: 'Llegó a una ciudad de dulce:\ncasas de cocada, calles de paçoca.\nLamió el poste de paleta\ny llovió confeti y palomitas!', hint: 'Haz clic en la paleta gigante para lamerla.', say: 'LAMBE!', done: 'QUE DULCE ES!' },
        'dragao': { title: 'El Dragón de Frijol', text: 'Pero en medio de la ciudad\nun dragón de frijol despertó.\nLanzó fuego de olla\ny su globo le robó!', hint: 'Haz clic en la nariz del dragón.', say: 'ACHIS!', done: 'EL DRAGON ESTORNUDO!' },
        'relogios': { title: 'La Guerra de los Relojes', text: 'En el reino de mil relojes\nel tiempo se dio vuelta.\nLa mandioca, con capa y valor,\njuró: Yo detengo esta revuelta!', hint: 'Haz clic en el reloj gigante para parar el tiempo.', say: 'TIC TAC!', done: 'EL TIEMPO SE DETUVO!' },
        'coliseu': { title: 'El Coliseo de las Mil Mandiocas', text: 'En el Coliseo de las Mandiocas\nel pueblo gritaba: Atacar!\nCada una tenía un sabor\ny todas querían luchar.', hint: 'Haz clic en el público para hacer la ola.', say: 'OLA!', done: 'LA OLA DIO LA VUELTA!' },
        'galaxia': { title: 'La Vía Láctea de Pamonha', text: 'La galaxia era de pamonha,\nde hoja de maíz y crema.\nUn planeta de sandía giraba\ny la mandioca surfeaba en el cometa.', hint: 'Haz clic en los planetas para hacerlos girar.', say: 'GIRA!', done: 'TODO EN ORBITA!' },
        'rei': { title: 'El Rey Mandiocón', text: 'En el trono de raíz y rayo\nse sentó el Rey Mandiocón.\nPero la chispa de la fogata\nse hizo espada en su mano.', hint: 'Haz clic en la espada para cargar la chispa.', say: 'ZZZAP!', done: 'ESPADA CARGADA!' },
        'bigbang': { title: 'El Big Bang Juninero', text: 'Bum! La chispa explotó\nen un mar de fuegos artificiales.\nEl rey se hizo confeti y fiesta\ny el universo, un buen inicio.', hint: 'Haz clic en la chispa para la explosión.', say: 'BUM!', done: 'UN UNIVERSO NUEVO!' },
        'bandeirinhas': { title: 'El Camino de Banderitas', text: 'De las estrellas brotó un sendero\nde banderitas ondeando.\nA lo lejos sonaba un acordeón\ny dieron ganas de llegar.', hint: 'Haz clic en las banderitas para tocar las notas.', say: 'DO RE MI!', done: 'LA MUSICA MOSTRO EL CAMINO!' },
        'arcoiris': { title: 'El Puente del Arcoíris', text: 'Un arcoíris de maíz y dulce\nhizo un puente en el aire.\nY allá abajo, chiquitita,\nla fiesta, a brillar.', hint: 'Haz clic en el arcoíris para que brille.', say: 'BRILLA!', done: 'EL PUENTE SE ENCENDIO!' },
        'portao': { title: 'El Portón del Arraiá', text: 'Llegó al portón del arraiá\ncon la linterna en la mano.\nEl pueblo gritó: Llegó!\ny le abrió paso, de corazón.', hint: 'Haz clic en la campana del portón.', say: 'DONG!', done: 'LLEGO!' },
        'quadrilha': { title: 'La Cuadrilla de Todos', text: 'Juntó al conejo, al dragón y al rey\nen una cuadrilla de lujo.\nAnarriê! gritó la marcadora\ny el mundo entero a bailar.', hint: 'Haz clic en la marcadora para gritar anarriê.', say: 'ANARRIE!', done: 'TODOS GIRARON!' },
        'festa': { title: 'La Fiesta Es Tuya', text: 'Y la fiesta que ella buscaba\nes esta que tú haces:\nfogata, acordeón y banderitas\ncon {n} invitados y más!', hint: 'Haz clic para lanzar los fuegos de tu fiesta.', say: 'PUM PUM!', done: 'LA FIESTA ES TUYA!' }
      },
